/**
 * Shared per-server DISK EXPANSION core — the money path for growing a single
 * server's OWN root disk without touching its plan's CPU/RAM/price.
 *
 * Used by the wallet flow (lib/actions-disk.ts expandServerDisk) and by the
 * Stripe confirm route so a paid checkout can apply the expansion immediately.
 * Plain server module (NOT "use server") — same shape as lib/resize.ts, and it
 * deliberately mirrors that file line-for-line so the two money paths can never
 * drift apart.
 *
 * ─── GROWTH IS ONE-WAY ──────────────────────────────────────────────────────
 * There is no shrink counterpart to `applyDiskExpand`, and nothing here (or
 * anywhere else) ever decrements `Server.extraDiskGB`.
 *
 * ─── WHY THIS CANNOT DOUBLE-CHARGE ──────────────────────────────────────────
 *  1. `diskExpandQuote` is the ONLY place the prorated amount is computed, and
 *     both the wallet path and the Stripe-confirm path call it.
 *  2. The wallet is debited exactly once, inside the same $transaction that
 *     creates the DISK_EXPAND job — a rolled-back debit leaves no job, and a
 *     job that exists was always paid for.
 *  3. On the card path the wallet is NOT touched until Stripe clears: checkout
 *     charges only the card remainder, the confirm route credits that remainder
 *     to the wallet and then debits the FULL proration, so the two net out.
 *  4. `creditCheckoutSession`'s UNIQUE(stripeSessionId) makes the confirm route
 *     idempotent — a reloaded/replayed confirm URL credits (and therefore
 *     applies) nothing a second time.
 *  5. `Server.extraDiskGB` is advanced by the WORKER on success, never here, so
 *     a failed expansion is refunded by the worker's reconcile pass and the
 *     customer never renews on storage they didn't get.
 */
import { db } from "./db";
import { debitWallet, InsufficientBalanceError } from "./wallet";
import { invoiceCreateData } from "./invoices";
import { getSettingInt } from "./settings";
import { diskCapacityCheck } from "./capacity";
import { remainingMonths } from "./proration";
import {
  EXTRA_DISK_DEFAULT_PER_GB_CENTS,
  EXTRA_DISK_MAX_TOTAL_GB,
  EXTRA_DISK_MIN_GB,
  EXTRA_DISK_STEP_GB,
  baseDiskGBFor,
  effectiveDiskGB,
  extraDiskCentsAt,
  extraDiskLabel,
  extraDiskProrateCents,
  isValidExtraDiskAddGB,
} from "./extra-disk";

export class DiskExpandError extends Error {}

/**
 * The per-GB/month price actually charged, from the admin setting
 * (`extra_disk_gb_price_cents`, default 10 = $0.10/GB/mo). Single source of
 * truth for every order/expansion/renewal/display path so they can't disagree.
 */
export async function extraDiskPerGbCents(): Promise<number> {
  const v = await getSettingInt("extra_disk_gb_price_cents", EXTRA_DISK_DEFAULT_PER_GB_CENTS);
  return Math.max(0, Math.round(v));
}

/** Monthly charge (integer cents) for `gb` GB of extra disk at the current price. */
export async function extraDiskMonthlyCents(gb: number): Promise<number> {
  if (!gb || gb <= 0) return 0;
  return extraDiskCentsAt(gb, await extraDiskPerGbCents());
}

type QuotedServer = NonNullable<Awaited<ReturnType<typeof loadServer>>>;

function loadServer(serverId: string) {
  return db.server.findUnique({ where: { id: serverId }, include: { plan: true, gamePlan: true } });
}

export type DiskExpandQuote = {
  server: QuotedServer;
  /** GB being added in THIS purchase. */
  addGB: number;
  /** `extraDiskGB` the server will hold once the worker finishes. */
  targetExtraDiskGB: number;
  /** Effective disk (plan + extra) after the expansion. */
  newTotalDiskGB: number;
  perGbCents: number;
  /** Recurring monthly cost of the newly-added GB (billed every renewal). */
  monthlyCents: number;
  /** One-off charge for the remainder of the CURRENT paid term. */
  prorateCents: number;
};

/**
 * Validate an expansion and compute the prorated charge over the ACTUAL
 * remaining duration — identical maths to `resizeQuote` (monthly cost × every
 * remaining month; null expiresAt on free/admin servers => 0). Throws
 * DiskExpandError with a user-facing message on any guard failure. Does NOT
 * check ownership — callers must do that.
 */
export async function diskExpandQuote(serverId: string, addGB: number): Promise<DiskExpandQuote> {
  const server = await loadServer(serverId);
  if (!server) throw new DiskExpandError("Not found");
  if (!isValidExtraDiskAddGB(addGB)) {
    throw new DiskExpandError(
      `Choose between ${EXTRA_DISK_MIN_GB} and 500 GB, in ${EXTRA_DISK_STEP_GB} GB steps.`,
    );
  }
  if (!["RUNNING", "STOPPED"].includes(server.status)) {
    throw new DiskExpandError("Server is busy — wait for the current operation to finish.");
  }
  if (!server.vmid) throw new DiskExpandError("This server hasn't finished provisioning yet.");

  const targetExtraDiskGB = server.extraDiskGB + addGB;
  const newTotalDiskGB = effectiveDiskGB(baseDiskGBFor(server), targetExtraDiskGB);
  if (newTotalDiskGB > EXTRA_DISK_MAX_TOTAL_GB) {
    throw new DiskExpandError(
      `A server's disk tops out at ${EXTRA_DISK_MAX_TOTAL_GB} GB — this would take it to ${newTotalDiskGB} GB. Contact support for larger volumes.`,
    );
  }

  // Don't sell space the node can't physically back.
  const cap = await diskCapacityCheck(server.nodeId, addGB);
  if (!cap.ok) throw new DiskExpandError(cap.reason ?? "Not enough storage available right now.");

  const perGbCents = await extraDiskPerGbCents();
  const monthlyCents = extraDiskCentsAt(addGB, perGbCents);

  // The remaining-term maths comes from the two SHARED functions the "Add storage"
  // control also calls, so the figure the customer agreed to and the figure debited
  // here cannot be two different derivations of the same idea. This block used to
  // inline both — its own `remainingMonths` expression over a second copy of
  // `MS_PER_AVG_MONTH` re-exported from lib/resize.ts.
  let prorateCents = 0;
  if (!server.isFree && server.expiresAt) {
    prorateCents = extraDiskProrateCents(monthlyCents, remainingMonths(server.expiresAt, Date.now()));
  }
  return { server, addGB, targetExtraDiskGB, newTotalDiskGB, perGbCents, monthlyCents, prorateCents };
}

/**
 * Apply the expansion: (optionally) debit the wallet for the prorated charge,
 * record the wallet transaction + PAID invoice, and queue the DISK_EXPAND job the
 * worker performs on Proxmox + inside the guest. Re-validates every guard (size,
 * ceiling, steady state, one in-flight job) so it is safe to call from the
 * unauthenticated confirm route. Throws DiskExpandError on any guard failure.
 *
 * `chargeCents` overrides the recomputed proration — the paid path passes the
 * exact amount the customer paid into their wallet at checkout so the debit here
 * nets to zero against that credit (mirrors lib/resize.ts applyResize).
 *
 * NOTE: `Server.extraDiskGB` is deliberately NOT advanced here. The worker sets it
 * only after the disk really grew, so a failed job is refunded (see
 * reconcileFailedJob) and no renewal ever bills for space that wasn't delivered.
 */

